          "stepId": "dress-refrigerate",
          "name": "Dress slaw and refrigerate",
          "task": "fridge",
          "duration": {
            "type": "variable",
            "minSeconds": "45m",
            "maxSeconds": "1h30m",
            "defaultSeconds": "45m"
          },
          "startTrigger": { "type": "afterStep", "stepId": "whisk-dressing" }
        }
      ]
    },
