      "steps": [
        {
          "stepId": "light-kettle",
          "name": "Light kettle grill to a clean bed of coals",
          "task": "kettle",
          "duration": { "type": "fixed", "seconds": "25m" },
          "startTrigger": { "type": "programStartOffset", "offsetSeconds": 43380 }
        },
        {
          "stepId": "grill-sausages",
          "name": "Grill sausages",
          "task": "kettle",
          "duration": { "type": "fixed", "seconds": "14m" },
          "startTrigger": { "type": "afterStep", "stepId": "light-kettle" }
        },
        {
          "stepId": "grill-corn",
          "name": "Grill corn",
          "task": "kettle",
          "duration": { "type": "fixed", "seconds": "10m" },
          "startTrigger": { "type": "afterStep", "stepId": "grill-sausages" }
        },
        {
          "stepId": "toast-buns",
          "name": "Toast buns (last, so they stay warm)",
          "task": "kettle",
          "duration": { "type": "fixed", "seconds": "3m" },
          "startTrigger": { "type": "afterStep", "stepId": "grill-corn" }
        }
      ]
    },
